import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Header.css';

const Header = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <header className="header">
      <div className="header-container">
        <Link to="/" className="logo">
          <span className="logo-text">Houzz</span>
        </Link>
        
        <nav className={`nav ${isMenuOpen ? 'nav-open' : ''}`}>
          <ul className="nav-menu">
            <li><Link to="/" className="nav-link">Home</Link></li>
            <li><Link to="/photos" className="nav-link">Photos</Link></li>
            <li><Link to="/professionals" className="nav-link">Find Professionals</Link></li>
            <li><Link to="/" className="nav-link">Shop</Link></li>
            <li><Link to="/" className="nav-link">Stories</Link></li>
          </ul>
        </nav>

        <div className="header-actions">
          <div className="search-container">
            <input type="text" placeholder="Search..." className="search-input" />
            <button className="search-btn">🔍</button>
          </div>
          <button className="sign-in-btn">Sign In</button>
        </div>

        <button 
          className="mobile-menu-btn"
          onClick={() => setIsMenuOpen(!isMenuOpen)}
        >
          ☰
        </button>
      </div>
    </header>
  );
};

export default Header;
